fn broadcast(a: Vec<i8>, shape: Vec<u8>) -> Vec<Vec<i8>> {
    // Extract the dimensions R and C from the shape vector
    let r = shape[0] as usize;
    let c = shape[1] as usize;
    
    // Create a new matrix with dimensions R x C
    let mut matrix = vec![vec![0; c]; r];
    
    // Check if the length of the array matches R or C
    if a.len() == r {
        // Treat the array as a column vector
        for i in 0..r {
            matrix[i].copy_from_slice(&a);
        }
    } else if a.len() == c {
        // Treat the array as a row vector
        for i in 0..r {
            matrix[i].copy_from_slice(&a);
        }
    }
    
    matrix
}